import { Bar, BarChart, CartesianGrid, Legend, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { nomeMesCurto } from '../domain/date';
import { formatarMoeda } from '../domain/money';
import type { FatiaCategoria, PontoMensal } from '../domain/projecao';

const COR_RECEITA = '#1d4ed8';
const COR_DESPESA = '#c2410c';

const emReais = (centavos: number) => centavos / 100;
const rotuloEixo = (valor: unknown) => `R$ ${Number(valor).toLocaleString('pt-BR')}`;
const dica = (valor: unknown) => formatarMoeda(Math.round(Number(valor) * 100));

export function GraficoDespesasPorCategoria({ dados }: { dados: FatiaCategoria[] }) {
  const total = dados.reduce((s, d) => s + d.valor, 0);
  const pontos = dados.map((d) => ({ nome: d.nome, valor: emReais(d.valor) }));
  return (
    <div>
      <div role="img" aria-label="Gráfico de barras das despesas por categoria no mês" className="h-56 w-full">
        <ResponsiveContainer width="100%" height="100%" minWidth={0}>
          <BarChart data={pontos} layout="vertical" margin={{ left: 8, right: 16 }}>
            <CartesianGrid horizontal={false} strokeDasharray="3 3" />
            <XAxis type="number" tickFormatter={rotuloEixo} fontSize={12} />
            <YAxis type="category" dataKey="nome" width={92} fontSize={12} />
            <Tooltip formatter={dica} />
            <Bar dataKey="valor" name="Despesas" fill={COR_DESPESA} radius={[0, 4, 4, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
      <details className="mt-2 text-sm">
        <summary className="cursor-pointer text-emerald-800">Ver como tabela</summary>
        <table className="mt-2 w-full text-left" aria-label="Despesas por categoria">
          <thead>
            <tr className="text-slate-600">
              <th scope="col" className="py-1 font-medium">Categoria</th>
              <th scope="col" className="py-1 text-right font-medium">Valor</th>
            </tr>
          </thead>
          <tbody>
            {dados.map((d) => (
              <tr key={d.nome} className="border-t border-slate-200">
                <th scope="row" className="py-1 font-normal">{d.nome}</th>
                <td className="py-1 text-right tabular-nums">{formatarMoeda(d.valor)}</td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr className="border-t border-slate-300 font-medium">
              <th scope="row" className="py-1">Total</th>
              <td className="py-1 text-right tabular-nums" data-testid="total-categorias">{formatarMoeda(total)}</td>
            </tr>
          </tfoot>
        </table>
      </details>
    </div>
  );
}

export function GraficoReceitasDespesas({ dados }: { dados: PontoMensal[] }) {
  const pontos = dados.map((d) => ({ mes: nomeMesCurto(d.mes), Receitas: emReais(d.receitas), Despesas: emReais(d.despesas) }));
  return (
    <div>
      <div role="img" aria-label="Gráfico de barras de receitas e despesas dos últimos 6 meses" className="h-56 w-full">
        <ResponsiveContainer width="100%" height="100%" minWidth={0}>
          <BarChart data={pontos} margin={{ left: 8, right: 8 }}>
            <CartesianGrid vertical={false} strokeDasharray="3 3" />
            <XAxis dataKey="mes" fontSize={12} />
            <YAxis tickFormatter={rotuloEixo} fontSize={12} width={72} />
            <Tooltip formatter={dica} />
            <Legend />
            <Bar dataKey="Receitas" fill={COR_RECEITA} radius={[4, 4, 0, 0]} />
            <Bar dataKey="Despesas" fill={COR_DESPESA} radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
      <details className="mt-2 text-sm">
        <summary className="cursor-pointer text-emerald-800">Ver como tabela</summary>
        <table className="mt-2 w-full text-left" aria-label="Receitas e despesas por mês">
          <thead>
            <tr className="text-slate-600">
              <th scope="col" className="py-1 font-medium">Mês</th>
              <th scope="col" className="py-1 text-right font-medium">Receitas</th>
              <th scope="col" className="py-1 text-right font-medium">Despesas</th>
            </tr>
          </thead>
          <tbody>
            {dados.map((d) => (
              <tr key={d.mes} className="border-t border-slate-200">
                <th scope="row" className="py-1 font-normal">{nomeMesCurto(d.mes)}</th>
                <td className="py-1 text-right tabular-nums">{formatarMoeda(d.receitas)}</td>
                <td className="py-1 text-right tabular-nums">{formatarMoeda(d.despesas)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </details>
    </div>
  );
}
=== ProjecaoCard
import { nomeMes } from '../domain/date';
import { formatarMoeda } from '../domain/money';
import type { Projecao } from '../domain/projecao';
import type { Categoria } from '../domain/types';
import { Alerta, Cartao, Valor } from './ui';

export function ProjecaoCard({ projecao, categorias }: { projecao: Projecao; categorias: Categoria[] }) {
  if (projecao.tipo === 'sem-dados') {
    return (
      <Cartao titulo="Projeção do saldo">
        <p className="text-sm text-slate-700" data-testid="projecao-vazia">
          Ainda não há um mês completo de transações nem recorrências ativas para projetar. Registre transações ou cadastre recorrências abaixo.
        </p>
      </Cartao>
    );
  }
  const nomes = new Map(categorias.map((c) => [c.id, c.nome]));
  const n = projecao.mesesBase.length;
  return (
    <Cartao titulo="Projeção do saldo">
      <p className="mb-3 text-sm text-slate-700">
        Estimativa para os próximos 6 meses, não uma garantia. Parte do saldo atual de <strong>{formatarMoeda(projecao.saldoAtual)}</strong> e soma o efeito mensal abaixo a cada mês.
      </p>
      <dl className="mb-3 grid gap-2 text-sm sm:grid-cols-2 lg:grid-cols-4">
        <div>
          <dt className="text-slate-600">Média de receitas</dt>
          <dd data-testid="media-receitas">{formatarMoeda(projecao.mediaReceitas)}</dd>
        </div>
        <div>
          <dt className="text-slate-600">Média de despesas</dt>
          <dd data-testid="media-despesas">{formatarMoeda(projecao.mediaDespesas)}</dd>
        </div>
        <div>
          <dt className="text-slate-600">Recorrências (receitas − despesas)</dt>
          <dd data-testid="recorrencias-liquido">{formatarMoeda(projecao.receitasRecorrentes - projecao.despesasRecorrentes)}</dd>
        </div>
        <div>
          <dt className="text-slate-600">Efeito mensal</dt>
          <dd data-testid="efeito-mensal">
            <Valor centavos={projecao.efeitoMensal} texto={formatarMoeda(projecao.efeitoMensal)} />
          </dd>
        </div>
      </dl>
      <p className="mb-3 text-xs text-slate-600" data-testid="base-projecao">
        {n === 0
          ? 'Sem meses completos de histórico: a projeção usa apenas as recorrências.'
          : `Médias calculadas com ${n} ${n === 1 ? 'mês completo' : 'meses completos'} (${projecao.mesesBase.map(nomeMes).join(', ')}).`}
        {projecao.categoriasCobertas.length > 0
          ? ` Categorias com recorrência ativa, fora das médias: ${projecao.categoriasCobertas.map((id) => nomes.get(id) ?? id).join(', ')}.`
          : ''}
      </p>
      {projecao.primeiroNegativo ? (
        <div className="mb-3">
          <Alerta tipo="aviso">
            <span data-testid="aviso-negativo">Atenção: o saldo projetado fica negativo a partir de {nomeMes(projecao.primeiroNegativo)}.</span>
          </Alerta>
        </div>
      ) : null}
      <table className="w-full text-left text-sm" aria-label="Saldo projetado por mês">
        <thead>
          <tr className="text-slate-600">
            <th scope="col" className="py-1 font-medium">Fim de</th>
            <th scope="col" className="py-1 text-right font-medium">Saldo estimado</th>
          </tr>
        </thead>
        <tbody>
          {projecao.meses.map((p) => (
            <tr key={p.mes} className="border-t border-slate-200" data-testid={`projecao-${p.mes}`}>
              <th scope="row" className="py-1 font-normal capitalize">{nomeMes(p.mes)}</th>
              <td className="py-1 text-right">
                <Valor centavos={p.saldo} texto={formatarMoeda(p.saldo)} />
                {p.saldo < 0 ? <span className="ml-1 text-xs text-red-800">(negativo)</span> : null}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </Cartao>
  );
}
=== RecorrenciasPanel
import { useState, type FormEvent } from 'react';
import { formatarMoeda, parseValor, valorParaCampo } from '../domain/money';
import {
  RECORRENCIA_DESCRICAO_MAX,
  alternarRecorrencia,
  criarRecorrencia,
  editarRecorrencia,
  excluirRecorrencia,
} from '../domain/projecao';
import type { AppState, Recorrencia, Resultado, TipoMovimento } from '../domain/types';
import { useEstado, useStore } from '../state/store';
import { Alerta, Botao, CampoSelect, CampoTexto, Cartao } from './ui';

interface FormProps {
  estado: AppState;
  inicial?: Recorrencia;
  onSalvar: (dados: { descricao: string; tipo: TipoMovimento; valor: number; categoriaId: string }) => Resultado<void>;
  onCancelar?: () => void;
}

type Erros = Partial<Record<'descricao' | 'valor' | 'categoriaId' | 'geral', string>>;

function RecorrenciaForm({ estado, inicial, onSalvar, onCancelar }: FormProps) {
  const [descricao, setDescricao] = useState(inicial?.descricao ?? '');
  const [tipo, setTipo] = useState<TipoMovimento>(inicial?.tipo ?? 'despesa');
  const [valor, setValor] = useState(inicial ? valorParaCampo(inicial.valor) : '');
  const [categoriaId, setCategoriaId] = useState(inicial?.categoriaId ?? '');
  const [erros, setErros] = useState<Erros>({});
  const categorias = estado.categorias.filter((c) => c.tipo === tipo && (!c.arquivada || c.id === inicial?.categoriaId));

  const enviar = (e: FormEvent) => {
    e.preventDefault();
    const centavos = parseValor(valor);
    if (centavos === null) return setErros({ valor: 'Informe um valor válido, como 1.500,00.' });
    const r = onSalvar({ descricao, tipo, valor: centavos, categoriaId });
    if (!r.ok) return setErros(r.campo ? { [r.campo]: r.erro } : { geral: r.erro });
    setErros({});
    if (!inicial) {
      setDescricao('');
      setValor('');
      setCategoriaId('');
    }
  };

  return (
    <form onSubmit={enviar} noValidate aria-label={inicial ? 'Editar recorrência' : 'Nova recorrência'} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
      <CampoTexto label="Descrição da recorrência" value={descricao} onChange={(e) => setDescricao(e.target.value)} erro={erros.descricao} maxLength={RECORRENCIA_DESCRICAO_MAX + 20} autoComplete="off" />
      <CampoSelect
        label="Tipo da recorrência"
        value={tipo}
        onChange={(e) => {
          setTipo(e.target.value as TipoMovimento);
          setCategoriaId('');
        }}
      >
        <option value="despesa">Despesa</option>
        <option value="receita">Receita</option>
      </CampoSelect>
      <CampoSelect label="Categoria da recorrência" value={categoriaId} onChange={(e) => setCategoriaId(e.target.value)} erro={erros.categoriaId}>
        <option value="">Selecione…</option>
        {categorias.map((c) => (
          <option key={c.id} value={c.id}>
            {c.nome}
          </option>
        ))}
      </CampoSelect>
      <CampoTexto label="Valor mensal" value={valor} onChange={(e) => setValor(e.target.value)} erro={erros.valor} inputMode="decimal" placeholder="0,00" />
      {erros.geral ? (
        <div className="sm:col-span-2 lg:col-span-4">
          <Alerta>{erros.geral}</Alerta>
        </div>
      ) : null}
      <div className="flex gap-2 sm:col-span-2 lg:col-span-4">
        <Botao type="submit">{inicial ? 'Salvar recorrência' : 'Adicionar recorrência'}</Botao>
        {onCancelar ? (
          <Botao variante="secundario" onClick={onCancelar}>
            Cancelar
          </Botao>
        ) : null}
      </div>
    </form>
  );
}

export function RecorrenciasPanel() {
  const store = useStore();
  const estado = useEstado();
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const nomeCategoria = new Map(estado.categorias.map((c) => [c.id, c.nome]));

  return (
    <Cartao titulo="Recorrências usadas na projeção">
      <p className="mb-3 text-sm text-slate-700">
        Valores fixos que se repetem todo mês, como salário e aluguel. Eles entram só na projeção: não criam transações nem mudam saldos. O histórico das categorias com recorrência ativa sai do cálculo das médias para não contar duas vezes.
      </p>
      {estado.recorrencias.length === 0 ? (
        <p className="mb-3 text-sm text-slate-600">Nenhuma recorrência cadastrada.</p>
      ) : (
        <ul className="mb-4 divide-y divide-slate-200" aria-label="Recorrências">
          {estado.recorrencias.map((r) =>
            editandoId === r.id ? (
              <li key={r.id} className="py-3">
                <RecorrenciaForm
                  estado={estado}
                  inicial={r}
                  onCancelar={() => setEditandoId(null)}
                  onSalvar={(dados) => {
                    const res = store.aplicar((s) => editarRecorrencia(s, r.id, dados));
                    if (res.ok) setEditandoId(null);
                    return res;
                  }}
                />
              </li>
            ) : (
              <li key={r.id} className="flex flex-wrap items-center justify-between gap-2 py-3">
                <div className="min-w-0">
                  <p className={`font-medium ${r.ativa ? 'text-slate-900' : 'text-slate-500 line-through'}`}>{r.descricao}</p>
                  <p className="text-xs text-slate-600">
                    {r.tipo === 'receita' ? 'Receita' : 'Despesa'} · {nomeCategoria.get(r.categoriaId) ?? 'Sem categoria'} · {formatarMoeda(r.valor)} por mês
                  </p>
                </div>
                <div className="flex flex-wrap items-center gap-2">
                  <label className="flex items-center gap-1.5 text-sm text-slate-800">
                    <input
                      type="checkbox"
                      checked={r.ativa}
                      aria-label={`Recorrência ${r.descricao} ativa`}
                      onChange={(e) => store.aplicar((s) => alternarRecorrencia(s, r.id, e.target.checked))}
                      className="h-4 w-4 accent-emerald-700"
                    />
                    Ativa
                  </label>
                  <Botao variante="secundario" aria-label={`Editar recorrência ${r.descricao}`} onClick={() => setEditandoId(r.id)}>
                    Editar
                  </Botao>
                  <Botao variante="perigo" aria-label={`Excluir recorrência ${r.descricao}`} onClick={() => store.aplicar((s) => excluirRecorrencia(s, r.id))}>
                    Excluir
                  </Botao>
                </div>
              </li>
            ),
          )}
        </ul>
      )}
      <RecorrenciaForm estado={estado} onSalvar={(dados) => store.aplicar((s) => criarRecorrencia(s, dados))} />
    </Cartao>
  );
}
=== LimiteCartaoBarra
import type { LimiteCartao } from '../domain/cartoes';
import { formatarMoeda, percentual } from '../domain/money';

export function LimiteCartaoBarra({ limite, total }: { limite: LimiteCartao; total: number }) {
  const pct = Math.min(Math.max(percentual(limite.usado, total), 0), 100);
  return (
    <div>
      <div
        role="progressbar"
        aria-label="Limite usado do cartão"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={pct}
        className="h-3 w-full overflow-hidden rounded-full bg-slate-200"
      >
        <div className={`h-full ${limite.excedido ? 'bg-red-600' : pct >= 80 ? 'bg-amber-500' : 'bg-sky-600'}`} style={{ width: `${pct}%` }} />
      </div>
      <dl className="mt-2 grid gap-2 text-sm sm:grid-cols-3">
        <div>
          <dt className="text-slate-600">Limite</dt>
          <dd data-testid="limite-total">{formatarMoeda(total)}</dd>
        </div>
        <div>
          <dt className="text-slate-600">Usado</dt>
          <dd data-testid="limite-usado">{formatarMoeda(limite.usado)}</dd>
        </div>
        <div>
          <dt className="text-slate-600">Disponível</dt>
          <dd data-testid="limite-disponivel">
            {limite.excedido ? `Limite excedido em ${formatarMoeda(-limite.disponivel)}` : formatarMoeda(limite.disponivel)}
          </dd>
        </div>
      </dl>
    </div>
  );
}
